import errno,os,subprocess,sys
master,slave=os.openpty();os.close(master)
try:
 try: os.write(slave,b"probe")
 except OSError as e: assert e.errno==errno.EIO
 else: raise AssertionError("closed PTY accepted a byte")
 script='clear -T xterm-256color; rc=$?; printf "%s\\n" "$rc" > status; exec 1>recovery; printf "recovered\\n"'
 run=subprocess.run([sys.argv[1],"--noprofile","--norc","-c",script],stdin=subprocess.DEVNULL,stdout=slave,stderr=subprocess.PIPE,timeout=5)
 sys.stdout.buffer.write(run.stderr);sys.exit(run.returncode)
finally: os.close(slave)
